"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7397],{7397:(e,a,t)=>{t.r(a),t.d(a,{default:()=>o});let o={correctChoiceId:"b",explanation:"Deliberation should scale with how hard a decision is to undo. Vendors can be switched, names changed, and layouts tested cheaply; a five-year lease locks in cost and location through several plausible futures.",work:["The lease fixes a commitment over five years; the other decisions can be changed more readily.","Lease payments and exit terms are not supplied, so the total financial commitment cannot be computed.","Compare reversibility and downside across plausible futures; devote deliberation to the harder-to-reverse choice."],takeaway:"Spend deliberation time in proportion to the cost of reversing a decision."}}}]);